            if not name or len(pw)<8 or not re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+',email) or email.rsplit('@',1)[-1]!=current_app.config['KREA_EMAIL_DOMAIN']:
                flash('Use your university email and a password of at least 8 characters.','error')
            elif get_db().execute('SELECT 1 FROM users WHERE email=?',(email,)).fetchone(): flash('An account with that email already exists.','error')
            else:
                cur=get_db().execute('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,? ,?)',(name,email,generate_password_hash(pw),'STUDENT')); get_db().commit(); audit(cur.lastrowid,'REGISTER','user',cur.lastrowid,'Student self-registration'); flash('Account created. Please sign in.','success'); return redirect(url_for('login'))
        return render_template('auth.html',register=True)
