        db=get_db(); scope=outlet_scope(g.user); start=request.args.get('from',date.today().isoformat()); end=request.args.get('to',date.today().isoformat()); clauses=['date(created_at)>=?','date(created_at)<=?']; args=[start,end]
        if scope is not None: clauses.append('outlet_id=?'); args.append(scope)
        where=' WHERE '+' AND '.join(clauses)
        summary=db.execute('SELECT status,count(*) n,coalesce(sum(CASE WHEN payment_status="PAID" OR payment_method="PAY_AT_PICKUP" THEN total_cents ELSE 0 END),0) cents FROM orders'+where+' GROUP BY status',args).fetchall()
        by_outlet=db.execute('SELECT x.name,count(o.id) orders,coalesce(sum(CASE WHEN o.status="COMPLETED" THEN o.total_cents ELSE 0 END),0) revenue FROM outlets x LEFT JOIN orders o ON o.outlet_id=x.id AND date(o.created_at)>=? AND date(o.created_at)<=?'+(' WHERE x.id=?' if scope is not None else '')+' GROUP BY x.id ORDER BY x.name',([start,end]+([scope] if scope is not None else []))).fetchall()
        return render_template('reports.html',summary=summary,by_outlet=by_outlet,start=start,end=end)
