import os, re, sqlite3, secrets, hashlib, hmac
from datetime import date
from functools import wraps
from flask import Flask, g, render_template, request, redirect, url_for, session, flash, abort, current_app
from werkzeug.security import generate_password_hash, check_password_hash
from werkzeug.utils import secure_filename

ROLES = ('STUDENT','STAFF','DH_MANAGER','ADMIN')
TRANSITIONS = {'PENDING': {'ACCEPTED','REJECTED','CANCELLED'}, 'ACCEPTED': {'PREPARING','CANCELLED'}, 'PREPARING': {'READY'}, 'READY': {'COMPLETED'}}

def create_app(test_config=None):
    app=Flask(__name__)
    app.config.from_object('config.Config')
    if test_config: app.config.update(test_config)
    for key in ('DATABASE_PATH','UPLOAD_FOLDER'):
        p=app.config[key]
        if not os.path.isabs(p): app.config[key]=os.path.join(app.root_path,'..',p)
        os.makedirs(os.path.dirname(app.config[key]) if key=='DATABASE_PATH' else app.config[key],exist_ok=True)
    @app.before_request
    def csrf_setup():
        if 'csrf' not in session: session['csrf']=secrets.token_urlsafe(24)
        if request.method=='POST' and not hmac.compare_digest(request.form.get('csrf_token',''),session['csrf']): abort(400,'Invalid CSRF token')
        g.user=get_db().execute('SELECT * FROM users WHERE id=? AND active=1',(session.get('user_id'),)).fetchone() if session.get('user_id') else None
    @app.context_processor
    def inject():
        unread=0
        if g.get('user'): unread=get_db().execute('SELECT count(*) FROM notifications WHERE user_id=? AND is_read=0',(g.user['id'],)).fetchone()[0]
        return {'current_user':g.get('user'),'unread_count':unread,'csrf_token':session.get('csrf','')}
    @app.teardown_appcontext
    def close_db(exc):
        db=g.pop('db',None)
        if db is not None: db.close()
    @app.cli.command('init-db')
    def init_db_cmd(): init_db(); print('Database initialized.')
    @app.route('/')
    def index():
        if not g.user: return redirect(url_for('login'))
        return redirect(url_for('dashboard'))
    @app.route('/register',methods=['GET','POST'])
    def register():
        if request.method=='POST':
            name=request.form.get('name','').strip(); email=request.form.get('email','').strip().lower(); pw=request.form.get('password','')
            if not name or len(pw)<8 or not re.fullmatch(r'[^@\s]+@[^@\s]+\.[^@\s]+',email) or email.rsplit('@',1)[-1]!=current_app.config['KREA_EMAIL_DOMAIN']:
                flash('Use your university email and a password of at least 8 characters.','error')
            elif get_db().execute('SELECT 1 FROM users WHERE email=?',(email,)).fetchone(): flash('An account with that email already exists.','error')
            else:
                cur=get_db().execute('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,? ,?)',(name,email,generate_password_hash(pw),'STUDENT')); get_db().commit(); audit(cur.lastrowid,'REGISTER','user',cur.lastrowid,'Student self-registration'); flash('Account created. Please sign in.','success'); return redirect(url_for('login'))
        return render_template('auth.html',register=True)
    @app.route('/login',methods=['GET','POST'])
    def login():
        if request.method=='POST':
            email=request.form.get('email','').strip().lower(); user=get_db().execute('SELECT * FROM users WHERE email=?',(email,)).fetchone()
            if not user or not check_password_hash(user['password_hash'],request.form.get('password','')) or not user['active']:
                audit(user['id'] if user else None,'LOGIN_FAILURE','user',user['id'] if user else None,'Invalid credentials or inactive account'); flash('Sign-in failed. Check your details or account status.','error')
            else:
                session.clear(); session['csrf']=secrets.token_urlsafe(24); session['user_id']=user['id']; audit(user['id'],'LOGIN','user',user['id'],'Successful login'); return redirect(url_for('dashboard'))
        return render_template('auth.html',register=False)
    @app.post('/logout')
    def logout(): session.clear(); flash('Signed out.','success'); return redirect(url_for('login'))
    @app.errorhandler(403)
    def forbidden(e): return render_template('error.html',code=403,message='You do not have access to this page.'),403
    @app.errorhandler(404)
    def missing(e): return render_template('error.html',code=404,message='That page or record could not be found.'),404
    @app.route('/dashboard')
    @login_required
    def dashboard():
        u=g.user
        if u['role']=='STUDENT':
            orders=get_db().execute('SELECT o.*,x.name outlet_name FROM orders o JOIN outlets x ON x.id=o.outlet_id WHERE user_id=? ORDER BY o.id DESC LIMIT 5',(u['id'],)).fetchall()
            outlets=get_db().execute('SELECT * FROM outlets WHERE active=1 ORDER BY name').fetchall()
            return render_template('student_dashboard.html',orders=orders,outlets=outlets)
        scope=outlet_scope(u); db=get_db(); cond=''; args=[]; raw_cond=''
        if scope is not None: cond=' WHERE o.outlet_id=?'; raw_cond=' WHERE outlet_id=?'; args=[scope]
        counts={s:db.execute('SELECT count(*) FROM orders'+raw_cond+(' AND' if raw_cond else ' WHERE')+' status=?',args+[s]).fetchone()[0] for s in ('PENDING','PREPARING','READY','COMPLETED','REJECTED')}
        today=db.execute('SELECT count(*) FROM orders'+raw_cond+(' AND' if raw_cond else ' WHERE')+' date(created_at)=?',args+[date.today().isoformat()]).fetchone()[0]
        orders=db.execute('SELECT o.*,u.name student,x.name outlet_name FROM orders o JOIN users u ON u.id=o.user_id JOIN outlets x ON x.id=o.outlet_id'+cond+' ORDER BY o.id DESC LIMIT 12',args).fetchall()
        low=db.execute('SELECT * FROM inventory_items WHERE active=1 AND quantity<=low_threshold'+(' AND outlet_id=?' if scope is not None else ''),( [scope] if scope is not None else [])).fetchall()
        return render_template('dashboard.html',counts=counts,today=today,orders=orders,low=low,scope=scope)
    @app.route('/outlets')
    @login_required
    @roles('STUDENT','ADMIN')
    def outlets(): return render_template('outlets.html',outlets=get_db().execute('SELECT * FROM outlets WHERE active=1 ORDER BY name').fetchall())
    @app.route('/outlet/<int:outlet_id>')
    @login_required
    def outlet(outlet_id):
        o=get_db().execute('SELECT * FROM outlets WHERE id=? AND active=1',(outlet_id,)).fetchone()
        if not o: abort(404)
        if g.user['role'] not in ('STUDENT','ADMIN') and outlet_scope(g.user)!=outlet_id: abort(403)
        cats=get_db().execute('SELECT * FROM menu_categories WHERE outlet_id=? ORDER BY name',(outlet_id,)).fetchall()
        items=get_db().execute('SELECT m.*,c.name category,coalesce(i.quantity,999999) stock FROM menu_items m LEFT JOIN menu_categories c ON c.id=m.category_id LEFT JOIN inventory_items i ON i.id=m.inventory_id WHERE m.outlet_id=? AND m.active=1 ORDER BY c.name,m.name',(outlet_id,)).fetchall()
        return render_template('menu.html',outlet=o,categories=cats,items=items)
    @app.post('/cart/add/<int:item_id>')
    @login_required
    @roles('STUDENT')
    def cart_add(item_id):
        db=get_db(); item=db.execute('SELECT m.*,i.quantity stock FROM menu_items m LEFT JOIN inventory_items i ON i.id=m.inventory_id WHERE m.id=? AND m.active=1',(item_id,)).fetchone(); qty=max(1,min(99,int(request.form.get('quantity',1) or 1)))
        if not item or not item['available'] or item['stock'] is not None and item['stock']<qty: flash('This item is unavailable or out of stock.','error')
        else:
            cart=session.get('cart',{})
            if cart and int(cart.get('outlet_id'))!=item['outlet_id']: flash('Your cart already contains another outlet. Clear it before switching outlets.','error')
            else:
                cart={'outlet_id':item['outlet_id'],'items':cart.get('items',{})}; cart['items'][str(item_id)]=min(99,int(cart['items'].get(str(item_id),0))+qty); session['cart']=cart; flash('Added to your cart.','success')
        return redirect(url_for('outlet',outlet_id=item['outlet_id'] if item else 1))
    @app.route('/cart',methods=['GET','POST'])
    @login_required
    @roles('STUDENT')
    def cart():
        db=get_db(); data=session.get('cart',{'items':{}})
        if request.method=='POST':
            if request.form.get('action')=='clear': session.pop('cart',None)
            else:
                for iid in list(data.get('items',{})):
                    val=request.form.get('qty_'+iid)
                    if val is not None:
                        try: n=int(val)
                        except ValueError: n=0
                        if n<=0: data['items'].pop(iid,None)
                        else: data['items'][iid]=min(99,n)
                if not data.get('items'): session.pop('cart',None)
                else: session['cart']=data
            return redirect(url_for('cart'))
