app\templates\orders.html:1:{% extends 'base.html' %}{% block content %}<div class="page-head"><div><div class="eyebrow">ORDER ACTIVITY</div><h1>{{ 'Your orders' if current_user.role=='STUDENT' else 'Incoming orders' }}</h1><p class="muted">{{ 'Track your campus meal from order to pickup.' if current_user.role=='STUDENT' else 'Orders shown here belong to your assigned outlet.' }}</p></div></div>{% if orders %}<div class="table-wrap"><table><thead><tr><th>Order</th><th>{% if current_user.role=='STUDENT' %}Outlet{% else %}Student / Outlet{% endif %}</th><th>Time</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody>{% for o in orders %}<tr><td>{{ o.order_number }}</td><td>{% if current_user.role!='STUDENT' %}{{ o.student }} · {% endif %}{{ o.outlet_name }}</td><td>{{ o.created_at }}</td><td>{{ o.payment_method|replace('_',' ') }}</td><td><span class="status {{ o.status|lower }}">{{ o.status }}</span></td><td><a href="{{ url_for('order_detail',order_id=o.id) }}">Details →</a></td></tr>{% endfor %}</tbody></table></div>{% else %}<div class="empty">No orders to show yet.</div>{% endif %}{% endblock %}
--
app\templates\dashboard.html:1:{% extends 'base.html' %}{% block title %}{{ current_user.role|replace('_',' ')|title }} dashboard{% endblock %}{% block content %}<div class="page-head"><div><div class="eyebrow">OPERATIONS · {{ 'ALL OUTLETS' if scope is none else 'YOUR OUTLET' }}</div><h1>{{ 'System overview' if current_user.role=='ADMIN' else 'Good shift, ' + current_user.name.split(' ')[0] }}</h1><p class="muted">A live view of today’s orders and service needs.</p></div><a class="button" href="{{ url_for('orders') }}">Manage orders →</a></div><div class="stats"><div class="card stat"><span>Today’s orders</span><strong>{{ today }}</strong></div>{% for status,count in counts.items() %}<div class="card stat"><span>{{ status|title }}</span><strong>{{ count }}</strong></div>{% endfor %}</div><div class="section-head"><div><div class="eyebrow">LATEST ACTIVITY</div><h2>Incoming orders</h2></div><a href="{{ url_for('orders') }}">All orders →</a></div>{% if orders %}<div class="table-wrap"><table><thead><tr><th>Order</th><th>Student</th><th>Outlet</th><th>Payment</th><th>Status</th><th></th></tr></thead><tbody>{% for o in orders %}<tr><td>{{ o.order_number }}</td><td>{{ o.student }}</td><td>{{ o.outlet_name }}</td><td>{{ o.payment_method|replace('_',' ') }}</td><td><span class="status {{ o.status|lower }}">{{ o.status }}</span></td><td><a href="{{ url_for('order_detail',order_id=o.id) }}">Open →</a></td></tr>{% endfor %}</tbody></table></div>{% else %}<div class="empty">No orders yet. New orders will appear here.</div>{% endif %}<div class="section-head"><div><div class="eyebrow">STOCK HEALTH</div><h2>Low-stock alerts</h2></div><a href="{{ url_for('inventory') }}">Manage inventory →</a></div>{% if low %}<div class="grid">{% for i in low %}<div class="card alert-card"><span class="warning">LOW STOCK</span><h3>{{ i.item_name }}</h3><p>{{ i.quantity }} {{ i.unit }} left · threshold {{ i.low_threshold }}</p></div>{% endfor %}</div>{% else %}<div class="empty compact">Everything is above its low-stock threshold.</div>{% endif %}{% endblock %}
