    @roles('STUDENT','ADMIN')
    def outlets(): return render_template('outlets.html',outlets=get_db().execute('SELECT * FROM outlets WHERE active=1 ORDER BY name').fetchall())
    @app.route('/outlet/<int:outlet_id>')
    @login_required
    def outlet(outlet_id):
