    @app.route('/orders/<int:order_id>')
    @login_required
    def order_detail(order_id):
        db=get_db(); o=db.execute('SELECT o.*,x.name outlet_name,u.name student FROM orders o JOIN outlets x ON x.id=o.outlet_id JOIN users u ON u.id=o.user_id WHERE o.id=?',(order_id,)).fetchone()
        if not o: abort(404)
