                salt=secret['otp_hash'].split(':',1)[0]; otp=f'{int.from_bytes(hmac.new(current_app.config["SECRET_KEY"].encode(),(str(order_id)+salt).encode(),hashlib.sha256).digest()[:4],"big")%1000000:06d}'
        return render_template('order_detail.html',order=o,lines=lines,otp=otp)
    @app.post('/orders/<int:order_id>/status')
    @login_required
    @roles('STUDENT','STAFF','DH_MANAGER','ADMIN')
    def change_status(order_id):
        db=get_db(); o=db.execute('SELECT * FROM orders WHERE id=?',(order_id,)).fetchone()
        if not o: abort(404)
        if g.user['role']=='STUDENT' and (o['user_id']!=g.user['id'] or request.form.get('status')!='CANCELLED'): abort(403)
        if g.user['role'] in ('STAFF','DH_MANAGER') and o['outlet_id']!=outlet_scope(g.user): abort(403)
        target=request.form.get('status')
        if target=='COMPLETED': flash('Complete ready orders only through OTP verification.','error')
        elif target not in TRANSITIONS.get(o['status'],set()): flash('Invalid status transition.','error')
        else:
            db.execute('UPDATE orders SET status=? WHERE id=?',(target,order_id))
            if target=='READY':
                salt=secrets.token_hex(8); code=f'{int.from_bytes(hmac.new(current_app.config["SECRET_KEY"].encode(),(str(order_id)+salt).encode(),hashlib.sha256).digest()[:4],"big")%1000000:06d}'; digest=hashlib.sha256((salt+code).encode()).hexdigest(); db.execute('INSERT OR REPLACE INTO pickup_otps(order_id,otp_hash,used_at) VALUES(?,?,NULL)',(order_id,salt+':'+digest))
            if target in ('REJECTED','CANCELLED'):
                for line in db.execute('SELECT oi.quantity,m.inventory_id FROM order_items oi JOIN menu_items m ON m.id=oi.menu_item_id WHERE oi.order_id=?',(order_id,)).fetchall():
                    if line['inventory_id']:
                        db.execute('UPDATE inventory_items SET quantity=quantity+?,updated_at=CURRENT_TIMESTAMP WHERE id=?',(line['quantity'],line['inventory_id']))
                        db.execute('INSERT INTO inventory_adjustments(inventory_id,actor_id,delta,reason) VALUES(?,?,?,?)',(line['inventory_id'],g.user['id'],line['quantity'],'Restored for '+o['order_number']))
            db.commit(); audit(g.user['id'],'ORDER_STATUS','order',order_id,f'{o["status"]} -> {target}'); notify(o['user_id'],'Order '+target.lower(),f'Order {o["order_number"]} is now {target.lower()}.','order'); db.commit(); flash('Order updated.','success')
        return redirect(url_for('order_detail',order_id=order_id))
    @app.post('/orders/<int:order_id>/verify-otp')
    @login_required
    @roles('STAFF','DH_MANAGER','ADMIN')
    def verify_otp(order_id):
        db=get_db(); o=db.execute('SELECT * FROM orders WHERE id=?',(order_id,)).fetchone()
        if not o: abort(404)
        if g.user['role'] in ('STAFF','DH_MANAGER') and o['outlet_id']!=outlet_scope(g.user): abort(403)
        rec=db.execute('SELECT * FROM pickup_otps WHERE order_id=?',(order_id,)).fetchone(); code=request.form.get('otp','')
        good=False
        if rec and not rec['used_at'] and o['status']=='READY':
            salt,digest=rec['otp_hash'].split(':'); good=hmac.compare_digest(hashlib.sha256((salt+code).encode()).hexdigest(),digest)
        audit(g.user['id'],'OTP_VERIFY','order',order_id,'success' if good else 'failure')
        if good:
            db.execute('UPDATE pickup_otps SET used_at=CURRENT_TIMESTAMP WHERE order_id=?',(order_id,)); db.execute("UPDATE orders SET status='COMPLETED' WHERE id=?",(order_id,)); notify(o['user_id'],'Order completed',f'Order {o["order_number"]} was picked up.','order'); db.commit(); flash('OTP verified. Order completed.','success')
        else: db.commit(); flash('OTP is invalid, expired, or already used.','error')
        return redirect(url_for('order_detail',order_id=order_id))
